"use strict";(globalThis.webpackChunk_picteus_docs=globalThis.webpackChunk_picteus_docs||[]).push([[813],{3896(e){e.exports=JSON.parse('{"version":{"pluginId":"default","version":"current","label":"Next","banner":null,"badge":false,"noIndex":false,"className":"docs-version-current","isLast":true,"docsSidebars":{"setupSidebar":[{"type":"link","href":"/picteus/docs/setup/install","label":"Installation","docId":"setup/install","unlisted":false},{"type":"link","href":"/picteus/docs/setup/start","label":"Start","docId":"setup/start","unlisted":false},{"type":"link","href":"/picteus/docs/setup/files","label":"Files","docId":"setup/files","unlisted":false},{"type":"link","href":"/picteus/docs/setup/traces","label":"Traces","docId":"setup/traces","unlisted":false},{"type":"link","href":"/picteus/docs/setup/troubleshooting","label":"Troubleshooting","docId":"setup/troubleshooting","unlisted":false}],"manualSidebar":[{"type":"link","href":"/picteus/docs/manual/webservicesapi","label":"Web services API","docId":"manual/webservicesapi","unlisted":false},{"type":"link","href":"/picteus/docs/manual/databases","label":"Databases","docId":"manual/databases","unlisted":false},{"type":"link","href":"/picteus/docs/manual/facets","label":"Facets","docId":"manual/facets","unlisted":false},{"type":"link","href":"/picteus/docs/manual/tags","label":"Tags","docId":"manual/tags","unlisted":false},{"type":"link","href":"/picteus/docs/manual/features","label":"Features","docId":"manual/features","unlisted":false},{"type":"link","href":"/picteus/docs/manual/embedding","label":"Embeddings","docId":"manual/embedding","unlisted":false},{"type":"link","href":"/picteus/docs/manual/container","label":"Container image","docId":"manual/container","unlisted":false}],"developerSidebar":[{"type":"link","href":"/picteus/docs/developer/architecture","label":"Architecture","docId":"developer/architecture","unlisted":false},{"type":"link","href":"/picteus/docs/developer/build","label":"Build","docId":"developer/build","unlisted":false},{"type":"link","href":"/picteus/docs/developer/ci-cd","label":"Continuous integration (CI) & deployment (CD)","docId":"developer/ci-cd","unlisted":false}],"extensionsSidebar":[{"type":"link","href":"/picteus/docs/extensions/guide","label":"Guide","docId":"extensions/guide","unlisted":false},{"type":"category","label":"Reference","items":[{"type":"link","href":"/picteus/docs/extensions/reference/overview","label":"Overview","docId":"extensions/reference/overview","unlisted":false},{"type":"link","href":"/picteus/docs/extensions/reference/manifest","label":"Manifest","docId":"extensions/reference/manifest","unlisted":false},{"type":"link","href":"/picteus/docs/extensions/reference/class","label":"Class","docId":"extensions/reference/class","unlisted":false},{"type":"link","href":"/picteus/docs/extensions/reference/api","label":"API","docId":"extensions/reference/api","unlisted":false},{"type":"link","href":"/picteus/docs/extensions/reference/viewkit","label":"ViewKit","docId":"extensions/reference/viewkit","unlisted":false},{"type":"link","href":"/picteus/docs/extensions/reference/intents","label":"Intents","docId":"extensions/reference/intents","unlisted":false},{"type":"link","href":"/picteus/docs/extensions/reference/manual","label":"Manual","docId":"extensions/reference/manual","unlisted":false}],"collapsed":true,"collapsible":true,"href":"/picteus/docs/category/reference"},{"type":"link","href":"/picteus/docs/extensions/unpacked","label":"Unpacked extensions","docId":"extensions/unpacked","unlisted":false}]},"docs":{"developer/architecture":{"id":"developer/architecture","title":"Architecture","description":"This document specifies what are the components of the application.","sidebar":"developerSidebar"},"developer/build":{"id":"developer/build","title":"Build","description":"This document explains how to build and run the application from the source code, but also how to package and distribute it.","sidebar":"developerSidebar"},"developer/ci-cd":{"id":"developer/ci-cd","title":"Continuous integration (CI) & deployment (CD)","description":"This document provides information about the automated CI / CD pipelines and scripts used for managing, building, testing, packaging, and releasing the application components.","sidebar":"developerSidebar"},"extensions/guide":{"id":"extensions/guide","title":"Guide","description":"This documentation walks you through the development of a Picteus extension.","sidebar":"extensionsSidebar"},"extensions/reference/api":{"id":"extensions/reference/api","title":"API","description":"Picteus extension SDKs embed the entirety of the back-end REST web services API, completely generated from OpenAPI specifications. Extensions can interact with any back-end resource \u2014 images, repositories, collections, tags, features, secrets \u2014 without requiring manual HTTP request configuration.","sidebar":"extensionsSidebar"},"extensions/reference/class":{"id":"extensions/reference/class","title":"Class","description":"Every Picteus extension must define an implementation class that inherits from the PicteusExtension base class provided by the official SDK. This class acts as the core entry point of your extension, overloading lifecycle hooks, subscribing to domain events, handling UI commands, and coordinating interactions with the Picteus application.","sidebar":"extensionsSidebar"},"extensions/reference/intents":{"id":"extensions/reference/intents","title":"Intents","description":"This document describes SDK intents and provides comprehensive documentation on them.","sidebar":"extensionsSidebar"},"extensions/reference/manifest":{"id":"extensions/reference/manifest","title":"Manifest","description":"Every extension must include a manifest.json file in its root directory. This manifest acts as the formal contract between the application and the extension, defining metadata, required runtimes, execution instructions, event subscriptions, registered commands, settings schemas, and user interface elements.","sidebar":"extensionsSidebar"},"extensions/reference/manual":{"id":"extensions/reference/manual","title":"Manual","description":"The MANUAL.md file is an optional Markdown document located at the root of an extension directory. It acts as the user manual and contextual in-app documentation for the extension.","sidebar":"extensionsSidebar"},"extensions/reference/overview":{"id":"extensions/reference/overview","title":"Overview","description":"This documentation is a reference documentation for developers creating extensions for Picteus. Picteus extensions enable you to extend the application\'s capabilities with custom image processing algorithms, automated tagging and feature extraction, interactive user interfaces, external tool integrations, and custom workflow commands.","sidebar":"extensionsSidebar"},"extensions/reference/viewkit":{"id":"extensions/reference/viewkit","title":"ViewKit","description":"ViewKit is a visual grammar for describing how the UI features of an image should be displayed and laid out in the Picteus front-end application. It describes presentation: the elements to render, their order, their grouping, and their layout.","sidebar":"extensionsSidebar"},"extensions/unpacked":{"id":"extensions/unpacked","title":"Unpacked extensions","description":"This document explains what an \\"unpacked\\" extension is and how to leverage unpacked directories during development.","sidebar":"extensionsSidebar"},"manual/container":{"id":"manual/container","title":"Container image","description":"Picteus can run inside containerized environments \u2014 such as Docker, Podman, or LXC / LXD. The container image bundles the back-end REST server, the embedded front-end web application UI, the Chroma vector database, the extension runtimes, and the SDKs in a single self-contained package.","sidebar":"manualSidebar"},"manual/databases":{"id":"manual/databases","title":"Databases","description":"The Picteus back-end embeds two distinct, complementary database systems to manage and persist all application data: a relational SQL database for structured data and a vector database for high-dimensional vector embeddings.","sidebar":"manualSidebar"},"manual/embedding":{"id":"manual/embedding","title":"Embeddings","description":"In Picteus, a vector embedding is a high-dimensional numerical representation of an image, computed by a machine learning encoder model and stored in the embedded Chroma DB vector database. Embeddings capture semantic, aesthetic, or perceptual properties of images as floating-point vectors, enabling cross-modal similarity searches \u2014 such as finding images matching a text prompt or visually similar to a reference image \u2014 that are not achievable with relational keyword-based queries alone. Vector embeddings are part of the image enrichment facets triplet of Picteus \u2014 the high-level overview of which is documented in Facets.","sidebar":"manualSidebar"},"manual/facets":{"id":"manual/facets","title":"Facets","description":"In Picteus, facets represent the distinct dimensions of data and metadata that qualify an image beyond its raw binary file. Picteus distinguishes two categories of image data: built-in metadata \u2014 immutable intrinsic properties (EXIF, IPTC, XMP, ICC) extracted directly from the image file upon ingestion, which no extension can modify \u2014 and the image enrichment facets triplet \u2014 categorical tags, structured features, and vector embeddings \u2014 which are entirely computed and written by extensions or automated pipelines. Together, these dimensions enable multi-layered search, automated classification, dynamic UI presentations, and targeted extension workflows.","sidebar":"manualSidebar"},"manual/features":{"id":"manual/features","title":"Features","description":"In Picteus, an image feature is a structured, typed, and attributed metadata entity attached to an image, generated programmatically by extensions or automated analysis pipelines. Image features dramatically expand the descriptive knowledge attached to an image beyond conventional file-level metadata, enabling fine-grained search, structured generation provenance, and rich user interface visualizations. Structured features are part of the image enrichment facets triplet of Picteus \u2014 the high-level overview of which is documented in Facets.","sidebar":"manualSidebar"},"manual/tags":{"id":"manual/tags","title":"Tags","description":"In Picteus, an image tag is a lightweight, flat, categorical textual label attached to an image and attributed to a specific extension namespace. Tags provide a fast and flexible taxonomic layer that augments the metadata corpus of images, empowering fine-grained categorization, instant front-end filtering, dynamic smart collections, and conditional extension command gating. Categorical tags are part of the image enrichment facets triplet of Picteus \u2014 the high-level overview of which is documented in Facets.","sidebar":"manualSidebar"},"manual/webservicesapi":{"id":"manual/webservicesapi","title":"Web services API","description":"The Picteus back-end exposes an embedded HTTP server hosting a comprehensive REST web services API. Every action and capability available in the graphical user interface is backed by these web services, making Picteus completely operable via API calls from external tools, automation scripts, and custom integrations.","sidebar":"manualSidebar"},"setup/files":{"id":"setup/files","title":"Files","description":"The application takes great care not to pollute the computer it is installed. To that extent, it isolates and places all the files it downloads, installs and handles within a single folder.","sidebar":"setupSidebar"},"setup/install":{"id":"setup/install","title":"Installation","description":"Let\'s see how to download and install the application.","sidebar":"setupSidebar"},"setup/start":{"id":"setup/start","title":"Start","description":"Once the application is installed, you can launch it:","sidebar":"setupSidebar"},"setup/traces":{"id":"setup/traces","title":"Traces","description":"Picteus provides two complementary forms of traces that report on what the application is doing: activities, a user-friendly real-time feed exposed directly in the front-end interface, and logs, a comprehensive low-level record of all internal events produced by every process involved in the application\'s execution. Understanding both forms is valuable both for following the application\'s normal operation and for diagnosing unexpected behavior.","sidebar":"setupSidebar"},"setup/troubleshooting":{"id":"setup/troubleshooting","title":"Troubleshooting","description":"When encountering an unexpected behavior, processing failure, or extension issue in Picteus, a structured diagnostic workflow enables you to rapidly isolate the root cause. This guide outlines the progressive diagnostic steps \u2014 starting with the high-level activity feed, moving to consolidated log files and Chromium Developer Tools, and ultimately reporting unresolvable issues to the project issue tracker.","sidebar":"setupSidebar"}}}}')}}]);